    suspend fun toggleTaskCompletion(taskId: Long, timestamp: Long = System.currentTimeMillis())

    @Query("SELECT COUNT(*) FROM tasks WHERE isCompleted = 0")
    fun getPendingTaskCount(): Flow<Int>

    @Query("SELECT DISTINCT category FROM tasks")
