```kotlin
package com.todolist.app.data.notification

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import com.todolist.app.domain.repository.TaskRepository
import dagger.hilt.android.AndroidEntryPoint
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.launch
import javax.inject.Inject

@AndroidEntryPoint
class BootCompletedReceiver : BroadcastReceiver() {

    @Inject
    lateinit var taskRepository: TaskRepository

    @Inject
    lateinit var reminderManager: ReminderManager

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    override fun onReceive(context: Context, intent: Intent) {
        if (intent.action == Intent.ACTION_BOOT_COMPLETED) {
            // Reschedule all reminders after device reboot
            rescheduleReminders()
        }
    }

    private fun rescheduleReminders() {
        scope.launch {
            try {
                val tasksWithReminders = taskRepository.getTasksWithReminders().first()
                tasksWithReminders.forEach { task ->
                    if (task.reminderTime != null && task.reminderTime.time > System.currentTimeMillis()) {
                        reminderManager.scheduleReminder(task)
                    }
                }
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }
    }
}
