```kotlin
package com.todolist.app.presentation.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.todolist.app.data.notification.ReminderManager
import com.todolist.app.domain.model.Priority
import com.todolist.app.domain.model.Task
import com.todolist.app.domain.usecase.*
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.*
import kotlinx.coroutines.launch
import java.util.Date
import javax.inject.Inject

@HiltViewModel
class TaskViewModel @Inject constructor(
    private val getAllTasksUseCase: GetAllTasksUseCase,
    private val getTaskByIdUseCase: GetTaskByIdUseCase,
    private val insertTaskUseCase: InsertTaskUseCase,
    private val updateTaskUseCase: UpdateTaskUseCase,
    private val deleteTaskUseCase: DeleteTaskUseCase,
    private val toggleTaskCompletionUseCase: ToggleTaskCompletionUseCase,
    private val deleteAllCompletedTasksUseCase: DeleteAllCompletedTasksUseCase,
    private val reminderManager: ReminderManager
) : ViewModel() {

    private val _uiState = MutableStateFlow(TaskUiState())
    val uiState: StateFlow<TaskUiState> = _uiState.asStateFlow()

    private val _filterState = MutableStateFlow(FilterState())
    val filterState: StateFlow<FilterState> = _filterState.asStateFlow()

    private val _events = MutableSharedFlow<TaskEvent>()
    val events: SharedFlow<TaskEvent> = _events.asSharedFlow()

    init {
        loadAllTasks()
    }

    private fun loadAllTasks() {
        viewModelScope.launch {
            _uiState.update { it.copy(isLoading = true) }

            getAllTasksUseCase()
                .catch { e ->
                    _uiState.update { it.copy(isLoading = false, error = e.message) }
                }
                .collect { tasks ->
                    _uiState.update { state ->
                        state.copy(
                            isLoading = false,
                            allTasks = tasks,
                            filteredTasks = applyFilters(tasks, state),
                            error = null
                        )
                    }
                }
        }
    }

    fun applyFilters(tasks: List<Task> = _uiState.value.allTasks, state: TaskUiState = _uiState.value): List<Task> {
        val filter = _filterState.value
        var filtered = tasks

        // Apply completion filter
        filtered = when (filter.showCompleted) {
            true -> filtered
            false -> filtered.filter { !it.isCompleted }
        }

        // Apply priority filter
        if (filter.priority != null) {
            filtered = filtered.filter { it.priority == filter.priority }
        }

        // Apply category filter
        if (filter.category != null) {
            filtered = filtered.filter { it.category == filter.category }
        }

        // Apply search query
        if (filter.searchQuery.isNotBlank()) {
            val query = filter.searchQuery.lowercase()
            filtered = filtered.filter {
                it.title.lowercase().contains(query) ||
                it.description.lowercase().contains(query)
            }
        }

        // Apply sorting
        filtered = when (filter.sortBy) {
            SortBy.DUE_DATE -> filtered.sortedBy { it.dueDate ?: Date(Long.MAX_VALUE) }
            SortBy.PRIORITY -> filtered.sortedByDescending { it.priority.ordinal }
            SortBy.CREATED_DATE -> filtered.sortedByDescending { it.createdAt }
            SortBy.ALPHABETICAL -> filtered.sortedBy { it.title.lowercase() }
        }

        return filtered
    }

    fun updateFilter(filter: FilterState) {
        _filterState.value = filter
        _uiState.update { state ->
            state.copy(filteredTasks = applyFilters(state.allTasks, state))
        }
    }

    fun addTask(
        title: String,
        description: String,
        priority: Priority,
        dueDate: Date?,
        reminderTime: Date?,
        category: String
    ) {
        viewModelScope.launch {
            try {
                val task = Task(
                    title = title,
                    description = description,
                    priority = priority,
                    dueDate = dueDate,
                    reminderTime = reminderTime,
                    category = category
                )
                val taskId = insertTaskUseCase(task)

                // Schedule reminder if set
                if (reminderTime != null && reminderTime.time > System.currentTimeMillis()) {
                    reminderManager.scheduleReminder(task.copy(id = taskId))
                }

                _events.emit(TaskEvent.TaskAdded("Task added successfully!"))
            } catch (e: Exception) {
                _events.emit(TaskEvent.Error(e.message ?: "Failed to add task"))
            }
        }
    }

    fun updateTask(task: Task) {
        viewModelScope.launch {
            try {
                // Cancel old reminder
                reminderManager.cancelReminder(task.id)

                // Update task
                updateTaskUseCase(task.copy(updatedAt = Date()))

                // Schedule new reminder if set
                if (task.reminderTime != null && task.reminderTime.time > System.currentTimeMillis()) {
                    reminderManager.scheduleReminder(task)
                }

                _events.emit(TaskEvent.TaskUpdated("Task updated successfully!"))
            } catch (e: Exception) {
                _events.emit(TaskEvent.Error(e.message ?: "Failed to update task"))
            }
        }
    }

    fun deleteTask(task: Task) {
        viewModelScope.launch {
            try {
                reminderManager.cancelReminder(task.id)
                deleteTaskUseCase(task)
                _events.emit(TaskEvent.TaskDeleted("Task deleted"))
            } catch (e: Exception) {
                _events.emit(TaskEvent.Error(e.message ?: "Failed to delete task"))
            }
        }
    }

    fun toggleTaskCompletion(task: Task) {
        viewModelScope.launch {
            try {
                // Cancel reminder if task is completed
                if (!task.isCompleted) {
                    reminderManager.cancelReminder(task.id)
                }

                toggleTaskCompletionUseCase(task.id)

                val message = if (task.isCompleted) "Task marked as incomplete" else "Task completed!"
                _events.emit(TaskEvent.TaskUpdated(message))
            } catch (e: Exception) {
                _events.emit(TaskEvent.Error(e.message ?: "Failed to update task"))
            }
        }
    }

    fun deleteAllCompletedTasks() {
        viewModelScope.launch {
            try {
                deleteAllCompletedTasksUseCase()
                _events.emit(TaskEvent.TaskDeleted("All completed tasks deleted"))
            } catch (e: Exception) {
                _events.emit(TaskEvent.Error(e.message ?: "Failed to delete completed tasks"))
            }
        }
    }

    fun getTaskById(id: Long): Flow<Task?> = getTaskByIdUseCase(id)

    fun refreshTasks() {
        loadAllTasks()
    }
}

data class TaskUiState(
    val isLoading: Boolean = false,
    val allTasks: List<Task> = emptyList(),
    val filteredTasks: List<Task> = emptyList(),
    val error: String? = null
)

data class FilterState(
    val showCompleted: Boolean = true,
    val priority: Priority? = null,
    val category: String? = null,
    val searchQuery: String = "",
    val sortBy: SortBy = SortBy.CREATED_DATE
)

enum class SortBy {
    DUE_DATE,
    PRIORITY,
    CREATED_DATE,
    ALPHABETICAL
}

sealed class TaskEvent {
    data class TaskAdded(val message: String) : TaskEvent()
    data class TaskUpdated(val message: String) : TaskEvent()
    data class TaskDeleted(val message: String) : TaskEvent()
    data class Error(val message: String) : TaskEvent()
}
