        if (taskId != -1L) {
            // Navigate to task detail/edit
            val editIntent = Intent(this, AddEditTaskActivity::class.java)
            editIntent.putExtra(AddEditTaskActivity.EXTRA_TASK_ID, taskId)
            startActivity(editIntent)
        }
    }

    private fun setupRecyclerView() {
        taskAdapter = TaskAdapter(
            onTaskClick = { task ->
                val intent = Intent(this, AddEditTaskActivity::class.java)
                intent.putExtra(AddEditTaskActivity.EXTRA_TASK_ID, task.id)
                startActivity(intent)
            },
            onCheckChanged = { task ->
                viewModel.toggleTaskCompletion(task)
            },
            onDeleteClick = { task ->
                showDeleteConfirmation(task)
            }
        )

        binding.recyclerViewTasks.apply {
            adapter = taskAdapter
            layoutManager = LinearLayoutManager(this@MainActivity)
            setHasFixedSize(true)
        }

        // Setup swipe to delete
        val swipeHandler = object : ItemTouchHelper.SimpleCallback(
            0,
            ItemTouchHelper.LEFT or ItemTouchHelper.RIGHT
        ) {
            override fun onMove(
                recyclerView: RecyclerView,
                viewHolder: RecyclerView.ViewHolder,
                target: RecyclerView.ViewHolder
            ) = false

            override fun onSwiped(viewHolder: RecyclerView.ViewHolder, direction: Int) {
                val position = viewHolder.adapterPosition
                val task = taskAdapter.currentList[position]
                showDeleteConfirmation(task)
                taskAdapter.notifyItemChanged(position)
            }
        }
        ItemTouchHelper(swipeHandler).attachToRecyclerView(binding.recyclerViewTasks)
    }

    private fun setupSwipeRefresh() {
        binding.swipeRefreshLayout.setOnRefreshListener {
            viewModel.refreshTasks()
        }
        binding.swipeRefreshLayout.setColorSchemeResources(
            R.color.purple_500,
            R.color.teal_700
        )
    }

    private fun setupFab() {
        binding.fabAddTask.setOnClickListener {
            startActivity(Intent(this, AddEditTaskActivity::class.java))
        }
    }

    private fun setupSearch() {
        binding.searchView.setOnQueryTextListener(object : SearchView.OnQueryTextListener {
            override fun onQueryTextSubmit(query: String?): Boolean {
                return false
            }

            override fun onQueryTextChange(newText: String?): Boolean {
                val currentFilter = viewModel.filterState.value
                viewModel.updateFilter(currentFilter.copy(searchQuery = newText ?: ""))
                return true
            }
        })
    }

    private fun observeViewModel() {
        lifecycleScope.launch {
            repeatOnLifecycle(Lifecycle.State.STARTED) {
                launch {
                    viewModel.uiState.collect { state ->
                        binding.swipeRefreshLayout.isRefreshing = state.isLoading

                        if (state.filteredTasks.isEmpty() && !state.isLoading) {
                            binding.emptyStateLayout.visibility = View.VISIBLE
                            binding.recyclerViewTasks.visibility = View.GONE
                        } else {
                            binding.emptyStateLayout.visibility = View.GONE
                            binding.recyclerViewTasks.visibility = View.VISIBLE
                        }

                        taskAdapter.submitList(state.filteredTasks)

                        state.error?.let { error ->
                            Snackbar.make(binding.root, error, Snackbar.LENGTH_LONG).show()
                        }
                    }
                }

                launch {
                    viewModel.events.collect { event ->
                        when (event) {
                            is TaskEvent.TaskAdded -> {
                                Snackbar.make(binding.root, event.message, Snackbar.LENGTH_SHORT).show()
                            }
                            is TaskEvent.TaskUpdated -> {
                                Snackbar.make(binding.root, event.message, Snackbar.LENGTH_SHORT).show()
                            }
                            is TaskEvent.TaskDeleted -> {
                                Snackbar.make(binding.root, event.message, Snackbar.LENGTH_SHORT).show()
                            }
                            is TaskEvent.Error -> {
                                Snackbar.make(binding.root, event.message, Snackbar.LENGTH_LONG).show()
                            }
                        }
                    }
                }
            }
        }
    }

    private fun requestNotificationPermission() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            if (ContextCompat.checkSelfPermission(
                    this,
                    Manifest.permission.POST_NOTIFICATIONS
                ) != PackageManager.PERMISSION_GRANTED
            ) {
                notificationPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
            }
        }
    }

    private fun showDeleteConfirmation(task: Task) {
        AlertDialog.Builder(this)
            .setTitle("Delete Task")
            .setMessage("Are you sure you want to delete \"${task.title}\"?")
            .setPositiveButton("Delete") { _, _ ->
                viewModel.deleteTask(task)
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun showFilterDialog() {
        val currentFilter = viewModel.filterState.value
        val options = arrayOf(
            "All Tasks",
            "Pending Tasks",
            "Completed Tasks"
        )
        val selectedIndex = when {
            !currentFilter.showCompleted -> 1
            currentFilter.showCompleted && currentFilter.priority == null -> 0
            else -> 0
        }

        AlertDialog.Builder(this)
            .setTitle("Filter Tasks")
            .setSingleChoiceItems(options, selectedIndex) { dialog, which ->
                when (which) {
                    0 -> viewModel.updateFilter(currentFilter.copy(showCompleted = true, priority = null))
                    1 -> viewModel.updateFilter(currentFilter.copy(showCompleted = false, priority = null))
                    2 -> viewModel.updateFilter(currentFilter.copy(showCompleted = true))
                }
                dialog.dismiss()
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun showSortDialog() {
        val currentFilter = viewModel.filterState.value
        val options = arrayOf(
            "Due Date",
            "Priority",
            "Created Date",
            "Alphabetical"
        )
        val selectedIndex = currentFilter.sortBy.ordinal

        AlertDialog.Builder(this)
            .setTitle("Sort Tasks")
            .setSingleChoiceItems(options, selectedIndex) { dialog, which ->
                val sortBy = SortBy.entries[which]
                viewModel.updateFilter(currentFilter.copy(sortBy = sortBy))
                dialog.dismiss()
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun showPriorityFilterDialog() {
        val currentFilter = viewModel.filterState.value
        val options = arrayOf("All Priorities", "High", "Medium", "Low")
        val selectedIndex = when (currentFilter.priority) {
            null -> 0
            Priority.HIGH -> 1
            Priority.MEDIUM -> 2
            Priority.LOW -> 3
        }

        AlertDialog.Builder(this)
            .setTitle("Filter by Priority")
            .setSingleChoiceItems(options, selectedIndex) { dialog, which ->
                val priority = when (which) {
                    1 -> Priority.HIGH
                    2 -> Priority.MEDIUM
                    3 -> Priority.LOW
                    else -> null
                }
                viewModel.updateFilter(currentFilter.copy(priority = priority))
                dialog.dismiss()
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun showDeleteCompletedDialog() {
        AlertDialog.Builder(this)
            .setTitle("Delete Completed Tasks")
            .setMessage("Are you sure you want to delete all completed tasks?")
            .setPositiveButton("Delete All") { _, _ ->
                viewModel.deleteAllCompletedTasks()
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    override fun onCreateOptionsMenu(menu: Menu): Boolean {
        menuInflater.inflate(R.menu.menu_main, menu)
        return true
    }

    override fun onOptionsItemSelected(item: MenuItem): Boolean {
        return when (item.itemId) {
            R.id.action_filter -> {
                showFilterDialog()
                true
            }
            R.id.action_sort -> {
                showSortDialog()
                true
            }
            R.id.action_priority_filter -> {
                showPriorityFilterDialog()
                true
            }
            R.id.action_delete_completed -> {
                showDeleteCompletedDialog()
                true
            }
            else -> super.onOptionsItemSelected(item)
        }
    }
}
