```kotlin
package com.todolist.app.presentation.ui

import android.app.DatePickerDialog
import android.app.TimePickerDialog
import android.os.Bundle
import android.widget.ArrayAdapter
import android.widget.Toast
import androidx.activity.viewModels
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.lifecycleScope
import androidx.lifecycle.repeatOnLifecycle
import com.todolist.app.R
import com.todolist.app.databinding.ActivityAddEditTaskBinding
import com.todolist.app.domain.model.Priority
import com.todolist.app.domain.model.Task
import com.todolist.app.presentation.viewmodel.TaskEvent
import com.todolist.app.presentation.viewmodel.TaskViewModel
import dagger.hilt.android.AndroidEntryPoint
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.launch
import java.text.SimpleDateFormat
import java.util.*

@AndroidEntryPoint
class AddEditTaskActivity : AppCompatActivity() {

    private lateinit var binding: ActivityAddEditTaskBinding
    private val viewModel: TaskViewModel by viewModels()

    private var taskId: Long = -1
    private var existingTask: Task? = null
    private var selectedDueDate: Date? = null
    private var selectedReminderTime: Date? = null
    private var isReminderEnabled: Boolean = false

    private val dateFormat = SimpleDateFormat("MMM dd, yyyy", Locale.getDefault())
    private val timeFormat = SimpleDateFormat("hh:mm a", Locale.getDefault())

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityAddEditTaskBinding.inflate(layoutInflater)
        setContentView(binding.root)

        taskId = intent.getLongExtra(EXTRA_TASK_ID, -1)

        setupToolbar()
        setupPrioritySpinner()
        setupCategorySpinner()
        setupDateTimePickers()
        setupSaveButton()
        observeEvents()

        if (taskId != -1L) {
            loadExistingTask()
        }
    }

    private fun setupToolbar() {
        setSupportActionBar(binding.toolbar)
        supportActionBar?.apply {
            setDisplayHomeAsUpEnabled(true)
            title = if (taskId == -1L) "Add Task" else "Edit Task"
        }
        binding.toolbar.setNavigationOnClickListener { onBackPressedDispatcher.onBackPressed() }
    }

    private fun setupPrioritySpinner() {
        val priorities = Priority.entries.map { it.name.lowercase().replaceFirstChar { c -> c.uppercase() } }
        val adapter = ArrayAdapter(this, android.R.layout.simple_spinner_dropdown_item, priorities)
        binding.spinnerPriority.adapter = adapter
        binding.spinnerPriority.setSelection(Priority.MEDIUM.ordinal)
    }

    private fun setupCategorySpinner() {
        val categories = listOf(
            "General", "Work", "Personal", "Shopping", "Health", 
            "Study", "Finance", "Travel", "Family", "Other"
        )
        val adapter = ArrayAdapter(this, android.R.layout.simple_spinner_dropdown_item, categories)
        binding.spinnerCategory.adapter = adapter
    }

    private fun setupDateTimePickers() {
        binding.btnDueDate.setOnClickListener {
            showDatePicker { date ->
                selectedDueDate = date
                binding.btnDueDate.text = dateFormat.format(date)
            }
        }

        binding.btnClearDueDate.setOnClickListener {
            selectedDueDate = null
            binding.btnDueDate.text = "Select Due Date"
        }

        binding.switchReminder.setOnCheckedChangeListener { _, isChecked ->
            isReminderEnabled = isChecked
            binding.layoutReminderTime.visibility = if (isChecked) android.view.View.VISIBLE else android.view.View.GONE

            if (isChecked && selectedReminderTime == null) {
                // Default reminder to 1 hour from now
                val calendar = Calendar.getInstance()
                calendar.add(Calendar.HOUR_OF_DAY, 1)
                selectedReminderTime = calendar.time
                binding.btnReminderTime.text = timeFormat.format(calendar.time)
            }
        }

        binding.btnReminderTime.setOnClickListener {
            showDateTimePicker { dateTime ->
                selectedReminderTime = dateTime
                binding.btnReminderTime.text = "${dateFormat.format(dateTime)} ${timeFormat.format(dateTime)}"
            }
        }

        binding.btnClearReminder.setOnClickListener {
            selectedReminderTime = null
            binding.btnReminderTime.text = "Select Reminder Time"
        }
    }

    private fun showDatePicker(onDateSelected: (Date) -> Unit) {
        val calendar = Calendar.getInstance()
        selectedDueDate?.let { calendar.time = it }

        DatePickerDialog(
            this,
            { _, year, month, dayOfMonth ->
                val selectedCalendar = Calendar.getInstance()
                selectedCalendar.set(year, month, dayOfMonth)
                onDateSelected(selectedCalendar.time)
            },
            calendar.get(Calendar.YEAR),
            calendar.get(Calendar.MONTH),
            calendar.get(Calendar.DAY_OF_MONTH)
        ).apply {
            datePicker.minDate = System.currentTimeMillis()
        }.show()
    }

    private fun showDateTimePicker(onDateTimeSelected: (Date) -> Unit) {
        val calendar = Calendar.getInstance()
        selectedReminderTime?.let { calendar.time = it }

        DatePickerDialog(
            this,
            { _, year, month, dayOfMonth ->
                val timeCalendar = Calendar.getInstance()
                timeCalendar.set(year, month, dayOfMonth, calendar.get(Calendar.HOUR_OF_DAY), calendar.get(Calendar.MINUTE))

                TimePickerDialog(
                    this@AddEditTaskActivity,
                    { _, hourOfDay, minute ->
                        timeCalendar.set(Calendar.HOUR_OF_DAY, hourOfDay)
                        timeCalendar.set(Calendar.MINUTE, minute)

                        if (timeCalendar.timeInMillis > System.currentTimeMillis()) {
                            onDateTimeSelected(timeCalendar.time)
                        } else {
                            Toast.makeText(this, "Please select a future time", Toast.LENGTH_SHORT).show()
                        }
                    },
                    timeCalendar.get(Calendar.HOUR_OF_DAY),
                    timeCalendar.get(Calendar.MINUTE),
                    false
                ).show()
            },
            calendar.get(Calendar.YEAR),
            calendar.get(Calendar.MONTH),
            calendar.get(Calendar.DAY_OF_MONTH)
        ).apply {
            datePicker.minDate = System.currentTimeMillis()
        }.show()
    }

    private fun setupSaveButton() {
        binding.btnSave.setOnClickListener {
            if (validateInput()) {
                saveTask()
            }
        }
    }

    private fun validateInput(): Boolean {
        val title = binding.etTitle.text.toString().trim()

        if (title.isEmpty()) {
            binding.tilTitle.error = "Title is required"
            return false
        }

        if (title.length < 3) {
            binding.tilTitle.error = "Title must be at least 3 characters"
            return false
        }

        binding.tilTitle.error = null
        return true
    }

    private fun saveTask() {
        val title = binding.etTitle.text.toString().trim()
        val description = binding.etDescription.text.toString().trim()
        val priority = Priority.entries[binding.spinnerPriority.selectedItemPosition]
        val category = binding.spinnerCategory.selectedItem.toString()

        if (taskId == -1L) {
            // Add new task
            viewModel.addTask(
                title = title,
                description = description,
                priority = priority,
                dueDate = selectedDueDate,
                reminderTime = if (isReminderEnabled) selectedReminderTime else null,
                category = category
            )
        } else {
            // Update existing task
            existingTask?.let { task ->
                val updatedTask = task.copy(
                    title = title,
                    description = description,
                    priority = priority,
                    dueDate = selectedDueDate,
                    reminderTime = if (isReminderEnabled) selectedReminderTime else null,
                    category = category,
                    updatedAt = Date()
                )
                viewModel.updateTask(updatedTask)
            }
        }
    }

    private fun loadExistingTask() {
        lifecycleScope.launch {
            viewModel.getTaskById(taskId).collect { task ->
                task?.let {
                    existingTask = it
                    populateFields(it)
                }
            }
        }
    }

    private fun populateFields(task: Task) {
        binding.etTitle.setText(task.title)
        binding.etDescription.setText(task.description)
        binding.spinnerPriority.setSelection(task.priority.ordinal)

        val categories = listOf(
            "General", "Work", "Personal", "Shopping", "Health", 
            "Study", "Finance", "Travel", "Family", "Other"
        )
        val categoryIndex = categories.indexOf(task.category).takeIf { it >= 0 } ?: 0
        binding.spinnerCategory.setSelection(categoryIndex)

        task.dueDate?.let { date ->
            selectedDueDate = date
            binding.btnDueDate.text = dateFormat.format(date)
        }

        if (task.reminderTime != null) {
            isReminderEnabled = true
            binding.switchReminder.isChecked = true
            binding.layoutReminderTime.visibility = android.view.View.VISIBLE
            selectedReminderTime = task.reminderTime
            binding.btnReminderTime.text = "${dateFormat.format(task.reminderTime)} ${timeFormat.format(task.reminderTime)}"
        }
    }

    private fun observeEvents() {
        lifecycleScope.launch {
            repeatOnLifecycle(Lifecycle.State.STARTED) {
                viewModel.events.collect { event ->
                    when (event) {
                        is TaskEvent.TaskAdded -> {
                            Toast.makeText(this@AddEditTaskActivity, event.message, Toast.LENGTH_SHORT).show()
                            finish()
                        }
                        is TaskEvent.TaskUpdated -> {
                            Toast.makeText(this@AddEditTaskActivity, event.message, Toast.LENGTH_SHORT).show()
                            finish()
                        }
                        is TaskEvent.Error -> {
                            Toast.makeText(this@AddEditTaskActivity, event.message, Toast.LENGTH_LONG).show()
                        }
                        else -> {}
                    }
                }
            }
        }
    }

    companion object {
        const val EXTRA_TASK_ID = "extra_task_id"
    }
}
