```kotlin
package com.todolist.app.presentation.adapter

import android.graphics.Paint
import android.view.LayoutInflater
import android.view.ViewGroup
import androidx.core.content.ContextCompat
import androidx.recyclerview.widget.DiffUtil
import androidx.recyclerview.widget.ListAdapter
import androidx.recyclerview.widget.RecyclerView
import com.todolist.app.R
import com.todolist.app.databinding.ItemTaskBinding
import com.todolist.app.domain.model.Priority
import com.todolist.app.domain.model.Task
import java.text.SimpleDateFormat
import java.util.*

class TaskAdapter(
    private val onTaskClick: (Task) -> Unit,
    private val onCheckChanged: (Task) -> Unit,
    private val onDeleteClick: (Task) -> Unit
) : ListAdapter<Task, TaskAdapter.TaskViewHolder>(TaskDiffCallback()) {

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): TaskViewHolder {
        val binding = ItemTaskBinding.inflate(
            LayoutInflater.from(parent.context),
            parent,
            false
        )
        return TaskViewHolder(binding)
    }

    override fun onBindViewHolder(holder: TaskViewHolder, position: Int) {
        holder.bind(getItem(position))
    }

    inner class TaskViewHolder(
        private val binding: ItemTaskBinding
    ) : RecyclerView.ViewHolder(binding.root) {

        private val dateFormat = SimpleDateFormat("MMM dd, yyyy", Locale.getDefault())
        private val timeFormat = SimpleDateFormat("hh:mm a", Locale.getDefault())

        fun bind(task: Task) {
            binding.apply {
                tvTitle.text = task.title
                tvDescription.text = task.description
                tvDescription.visibility = if (task.description.isNotEmpty()) {
                    android.view.View.VISIBLE
                } else {
                    android.view.View.GONE
                }

                // Checkbox handling
                checkboxComplete.isChecked = task.isCompleted

                // Strikethrough for completed tasks
                if (task.isCompleted) {
                    tvTitle.paintFlags = tvTitle.paintFlags or Paint.STRIKE_THRU_TEXT_FLAG
                    tvTitle.alpha = 0.6f
                    tvDescription.alpha = 0.6f
                } else {
                    tvTitle.paintFlags = tvTitle.paintFlags and Paint.STRIKE_THRU_TEXT_FLAG.inv()
                    tvTitle.alpha = 1.0f
                    tvDescription.alpha = 1.0f
                }

                checkboxComplete.setOnClickListener {
                    onCheckChanged(task)
                }

                // Priority indicator
                val priorityColor = when (task.priority) {
                    Priority.HIGH -> R.color.priority_high
                    Priority.MEDIUM -> R.color.priority_medium
                    Priority.LOW -> R.color.priority_low
                }
                priorityIndicator.setBackgroundColor(
                    ContextCompat.getColor(itemView.context, priorityColor)
                )

                // Category chip
                chipCategory.text = task.category

                // Due date
                if (task.dueDate != null) {
                    layoutDueDate.visibility = android.view.View.VISIBLE
                    tvDueDate.text = dateFormat.format(task.dueDate)

                    // Change color if overdue
                    if (!task.isCompleted && task.dueDate.time < System.currentTimeMillis()) {
                        tvDueDate.setTextColor(ContextCompat.getColor(itemView.context, R.color.overdue))
                    } else {
                        tvDueDate.setTextColor(ContextCompat.getColor(itemView.context, R.color.text_secondary))
                    }
                } else {
                    layoutDueDate.visibility = android.view.View.GONE
                }

                // Reminder indicator
                if (task.reminderTime != null) {
                    layoutReminder.visibility = android.view.View.VISIBLE
                    tvReminderTime.text = "${dateFormat.format(task.reminderTime)} ${timeFormat.format(task.reminderTime)}"

                    // Check if reminder time has passed
                    if (task.reminderTime.time < System.currentTimeMillis() && !task.isCompleted) {
                        ivReminderIcon.setColorFilter(
                            ContextCompat.getColor(itemView.context, R.color.overdue)
                        )
                    }
                } else {
                    layoutReminder.visibility = android.view.View.GONE
                }

                // Click listeners
                root.setOnClickListener { onTaskClick(task) }
                btnDelete.setOnClickListener { onDeleteClick(task) }
            }
        }
    }

    class TaskDiffCallback : DiffUtil.ItemCallback<Task>() {
        override fun areItemsTheSame(oldItem: Task, newItem: Task): Boolean {
            return oldItem.id == newItem.id
        }

        override fun areContentsTheSame(oldItem: Task, newItem: Task): Boolean {
            return oldItem == newItem
        }
    }
}
